(function(){const pad=(n)=>String(n).padStart(2,'0');const ymd=(d)=>d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());const parse=(s)=>{const p=String(s||'').split('-').map(Number);return p.length===3&&p.every((n)=>Number.isFinite(n))?new Date(p[0],p[1]-1,p[2]):null;};const monday=(s)=>{const d=parse(s)||new Date();const wd=(d.getDay()+6)%7;d.setDate(d.getDate()-wd);return ymd(d);};
window.LG={areas:[['career','Career'],['finance','Finance'],['health','Health & Fitness'],['family','Family & Friends'],['romance','Romance'],['fun','Fun & Adventure'],['growth','Learning & Growth'],['spirituality','Spirituality'],['home','Home & Environment'],['contribution','Contribution & Giving']],none:'–',lime:'#B1E287',ink:'#272725',pad:pad,ymd:ymd,parse:parse,monday:monday,today:ymd(new Date()),week:monday(ymd(new Date())),day:ymd(new Date()),
monthLabel:(m)=>{const d=d3.utcParse('%Y-%m')(String(m||'').slice(0,7));return d?d3.utcFormat('%B %Y')(d):String(m||'');},
dayLabel:(s)=>{const d=parse(s);return d?d3.timeFormat('%a, %b %-d')(d):String(s||'');},
weekLabel:(s)=>{const d=parse(s);return d?'Week of '+d3.timeFormat('%b %-d')(d):String(s||'');},
empty:(el,txt)=>{const p=document.createElement('p');p.className='lg-empty';p.textContent=txt;el.append(p);},
rows:(id)=>{const d=dash.data(id);return d.status==='ok'&&Array.isArray(d.data)?d.data:[];},
tip:(box)=>{const t=document.createElement('div');t.className='lg-tip';t.hidden=true;box.append(t);return{show(lines,x,y){t.replaceChildren(...lines.map(([k,v])=>{const d=document.createElement('div');if(k){const s=document.createElement('span');s.className='lg-tip-k';s.textContent=k+': ';d.append(s);}d.append(document.createTextNode(v));return d;}));t.hidden=false;const bw=box.clientWidth;const tw=t.offsetWidth;let left=x+14;if(left+tw>bw)left=x-tw-14;if(left<0)left=0;t.style.left=left+'px';t.style.top=Math.max(0,y-12)+'px';},hide(){t.hidden=true;}};},
save:async(sub,id,row)=>{const [db,user]=await Promise.all([claude.use('db'),claude.use('user')]);const path=`data/users/${await user.id()}/life/${sub}`;if(id)await db.doc(path+'/'+id).set(row);else await db.collection(path).add(row);},
remove:async(sub,id)=>{const [db,user]=await Promise.all([claude.use('db'),claude.use('user')]);await db.doc(`data/users/${await user.id()}/life/${sub}/${id}`).delete();}};})();
dash.calc('history',{title:'Monthly life scores',description:'Each monthly check-in with its average across the 10 areas.',inputs:['checkins'],fn:(checkins)=>{const keys=['career','finance','health','family','romance','fun','growth','spirituality','home','contribution'];return (checkins||[]).filter((r)=>r&&String(r.month||'').length===7).map((r)=>{const row={month:String(r.month)};let sum=0,n=0;keys.forEach((k)=>{const v=r[k]===null||r[k]===undefined||r[k]===''?NaN:Number(r[k]);row[k]=Number.isFinite(v)?v:null;if(row[k]!==null){sum+=v;n+=1;}});row.avg=n?Math.round((sum/n)*10)/10:null;return row;}).sort((a,b)=>(a.month<b.month?-1:a.month>b.month?1:0));}});
dash.calc('latest',{title:'Latest month by area',description:'Each area’s score in your latest monthly check-in, beside the month before.',inputs:['history'],fn:(history)=>{const labels={career:'Career',finance:'Finance',health:'Health & Fitness',family:'Family & Friends',romance:'Romance',fun:'Fun & Adventure',growth:'Learning & Growth',spirituality:'Spirituality',home:'Home & Environment',contribution:'Contribution & Giving'};if(!Array.isArray(history)||!history.length)return [];const cur=history[history.length-1];const prev=history.length>1?history[history.length-2]:null;return Object.keys(labels).map((k)=>({area:k,label:labels[k],month:cur.month,score:cur[k],prev:prev?prev[k]:null,change:prev&&cur[k]!=null&&prev[k]!=null?cur[k]-prev[k]:null}));}});
dash.calc('summary',{title:'Life score at a glance',description:'Latest and all-time life score, its change, and your strongest and weakest areas.',inputs:['history','latest'],fn:(history,latest)=>{if(!Array.isArray(history)||!history.length)return [];const cur=history[history.length-1];const prev=history.length>1?history[history.length-2]:null;const scored=(latest||[]).filter((r)=>r.score!=null);const top=scored.slice().sort((a,b)=>b.score-a.score)[0];const low=scored.slice().sort((a,b)=>a.score-b.score)[0];const avgs=history.map((h)=>h.avg).filter((v)=>v!=null);return [{month:cur.month,avg:cur.avg,change:prev&&prev.avg!=null&&cur.avg!=null?Math.round((cur.avg-prev.avg)*10)/10:null,months:history.length,since:history[0].month,allTime:avgs.length?Math.round((avgs.reduce((a,b)=>a+b,0)/avgs.length)*10)/10:null,strongest:top?top.label:null,strongestScore:top?top.score:null,weakest:low?low.label:null,weakestScore:low?low.score:null}];}});
dash.calc('pulse',{title:'Daily and weekly pulse',description:'Days checked in this month, your current streak, how many area check-offs you hit, and your latest weekly score.',inputs:['days','weeks'],fn:(days,weeks)=>{const keys=['career','finance','health','family','romance','fun','growth','spirituality','home','contribution'];const pad=(n)=>String(n).padStart(2,'0');const ymd=(d)=>d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());const now=new Date();const month=ymd(now).slice(0,7);const list=(days||[]).filter((d)=>String(d.date||'').length===10);const logged=new Set(list.map((d)=>d.date));let streak=0;const cur=new Date(now.getFullYear(),now.getMonth(),now.getDate());if(!logged.has(ymd(cur)))cur.setDate(cur.getDate()-1);while(logged.has(ymd(cur))){streak+=1;cur.setDate(cur.getDate()-1);}const inMonth=list.filter((d)=>d.date.slice(0,7)===month);let hits=0;inMonth.forEach((d)=>keys.forEach((k)=>{if(d[k]===true)hits+=1;}));const ws=(weeks||[]).filter((w)=>String(w.week||'').length===10&&w.score!=null&&w.score!=='').sort((a,b)=>(a.week<b.week?-1:1));const lw=ws[ws.length-1];return [{month:month,daysLogged:inMonth.length,streak:streak,rate:inMonth.length?Math.round((hits/(inMonth.length*10))*100):null,week:lw?lw.week:null,weekScore:lw?Number(lw.score):null,weeksLogged:ws.length}];}});
dash.calc('dailyAreas',{title:'This month by area (daily)',description:'For each area, how many of this month’s daily check-ins you showed up for it.',inputs:['days'],fn:(days)=>{const labels={career:'Career',finance:'Finance',health:'Health & Fitness',family:'Family & Friends',romance:'Romance',fun:'Fun & Adventure',growth:'Learning & Growth',spirituality:'Spirituality',home:'Home & Environment',contribution:'Contribution & Giving'};const now=new Date();const month=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');const inMonth=(days||[]).filter((d)=>String(d.date||'').slice(0,7)===month);return Object.keys(labels).map((k)=>{const hits=inMonth.filter((d)=>d[k]===true).length;return {area:k,label:labels[k],hits:hits,days:inMonth.length,rate:inMonth.length?Math.round((hits/inMonth.length)*100):null};});}});
dash.calc('weekly',{title:'Weekly scores',description:'Each weekly check-in, oldest first.',inputs:['weeks'],fn:(weeks)=>(weeks||[]).filter((w)=>String(w.week||'').length===10).map((w)=>({week:w.week,score:w.score===''||w.score==null?null:Number(w.score)})).sort((a,b)=>(a.week<b.week?-1:1))});
dash.calc('dumpStats',{title:'The dump',description:'How many things you are still releasing and how many you have let go.',inputs:['letgo'],fn:(letgo)=>[{active:(letgo||[]).filter((r)=>!r.released).length,released:(letgo||[]).filter((r)=>r.released).length}]});

dash.calc('allWins',{title:'Every win',description:'Wins you logged on the win board, plus daily, weekly and monthly wins from your check-ins, newest first.',inputs:['wins','days','weeks','checkins'],fn:(wins,days,weeks,checkins)=>{const out=[];(wins||[]).forEach((w)=>{if(w&&w.text)out.push({id:'w-'+w.id,date:String(w.date||''),text:String(w.text),area:w.area||'',from:'Win board',doc:w.id});});(days||[]).forEach((d)=>{if(d&&d.win)out.push({id:'d-'+d.date,date:String(d.date),text:String(d.win),area:'',from:'Daily check-in'});});(weeks||[]).forEach((w)=>{if(w&&w.win)out.push({id:'k-'+w.week,date:String(w.week),text:String(w.win),area:'',from:'Weekly reset'});});(checkins||[]).forEach((c)=>{if(c&&c.win)out.push({id:'m-'+c.month,date:String(c.month)+'-01',text:String(c.win),area:'',from:'Monthly check-in'});});return out.sort((a,b)=>(a.date<b.date?1:a.date>b.date?-1:0));}});
dash.calc('winStats',{title:'Win count',description:'How many wins you have collected in total and this month.',inputs:['allWins'],fn:(allWins)=>{const now=new Date();const month=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');const list=allWins||[];return [{total:list.length,thisMonth:list.filter((w)=>String(w.date).slice(0,7)===month).length}];}});
